    -- -------------------------------------------------------------------------
    -- 3. Declare People and Organizations as overlapping IS-A parents
    -- -------------------------------------------------------------------------
    UPDATE __mj."Entity"
    SET "AllowMultipleSubtypes" = TRUE
    WHERE "ID" IN (v_people_entity_id, v_orgs_entity_id)
      AND "AllowMultipleSubtypes" = FALSE;
