    END LOOP;

        -- Cascade: Set MJ_BizApps_Common: Organizations.ParentID to NULL
    FOR v_rec IN
        SELECT "ID"
        FROM "__mj_bizappscommon"."Organization"
        WHERE "ParentID" = p_id
    LOOP
        -- Update related record to set FK to NULL
