CREATE OR REPLACE FUNCTION "__mj_bizappscommon"."spCreateActivityType"(
    p_id UUID DEFAULT NULL,
    p_code varchar(50) DEFAULT NULL,
    p_name varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_parentid_clear boolean DEFAULT false,
    p_parentid UUID DEFAULT NULL,
    p_iconclass_clear boolean DEFAULT false,
    p_iconclass varchar(100) DEFAULT NULL,
    p_color_clear boolean DEFAULT false,
    p_color varchar(30) DEFAULT NULL,
    p_sequence int DEFAULT NULL,
    p_issystem BOOLEAN DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj_bizappscommon"."vwActivityTypes" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."ActivityType"
        (
            "ID",
            "Code",
                "Name",
                "Description",
                "ParentID",
                "IconClass",
                "Color",
                "Sequence",
                "IsSystem",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_code,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_parentid_clear = true THEN NULL ELSE COALESCE(p_parentid, NULL) END,
                CASE WHEN p_iconclass_clear = true THEN NULL ELSE COALESCE(p_iconclass, NULL) END,
                CASE WHEN p_color_clear = true THEN NULL ELSE COALESCE(p_color, NULL) END,
                COALESCE(p_sequence, 0),
                COALESCE(p_issystem, FALSE),
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappscommon"."vwActivityTypes"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
