    p_provider varchar(40) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_direction varchar(20) DEFAULT NULL,
    p_owneruserid UUID DEFAULT NULL,
    p_credentialsref_clear boolean DEFAULT false,
    p_credentialsref varchar(200) DEFAULT NULL,
    p_mailbox_clear boolean DEFAULT false,
    p_mailbox varchar(320) DEFAULT NULL,
    p_lastsyncat_clear boolean DEFAULT false,
    p_lastsyncat TIMESTAMPTZ DEFAULT NULL,
    p_lasterror_clear boolean DEFAULT false,
    p_lasterror TEXT DEFAULT NULL,
    p_settings_clear boolean DEFAULT false,
    p_settings TEXT DEFAULT NULL
) RETURNS SETOF "__mj_bizappscommon"."vwActivitySyncConnections" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."ActivitySyncConnection"
        (
            "ID",
            "Name",
                "Provider",
                "Status",
                "Direction",
                "OwnerUserID",
                "CredentialsRef",
                "Mailbox",
                "LastSyncAt",
                "LastError",
                "Settings"
        )
    VALUES
        (
            v_new_id,
            p_name,
                p_provider,
                COALESCE(p_status, 'Active'),
                COALESCE(p_direction, 'Inbound'),
                p_owneruserid,
                CASE WHEN p_credentialsref_clear = true THEN NULL ELSE COALESCE(p_credentialsref, NULL) END,
                CASE WHEN p_mailbox_clear = true THEN NULL ELSE COALESCE(p_mailbox, NULL) END,
                CASE WHEN p_lastsyncat_clear = true THEN NULL ELSE COALESCE(p_lastsyncat, NULL) END,
                CASE WHEN p_lasterror_clear = true THEN NULL ELSE COALESCE(p_lasterror, NULL) END,
                CASE WHEN p_settings_clear = true THEN NULL ELSE COALESCE(p_settings, NULL) END
