  CONSTRAINT "FK_ActivitySyncRuleSet_ProviderType" FOREIGN KEY ("ActivitySyncProviderTypeID") REFERENCES "__mj_bizappscommon"."ActivitySyncProviderType" (
    "ID"
  )
);

-- batch H3
CREATE TABLE "__mj_bizappscommon"."ActivitySyncConnectionRuleSet" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "ActivitySyncConnectionID" UUID NOT NULL,
  "ActivitySyncRuleSetID" UUID NOT NULL,
  "Sequence" INT NOT NULL DEFAULT 0,
  "IsEnabled" BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT "PK_ActivitySyncConnectionRuleSet" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_ActivitySyncConnectionRuleSet" UNIQUE (
    "ActivitySyncConnectionID",
    "ActivitySyncRuleSetID"
  ),
  CONSTRAINT "FK_ActivitySyncConnectionRuleSet_Connection" FOREIGN KEY ("ActivitySyncConnectionID") REFERENCES "__mj_bizappscommon"."ActivitySyncConnection" (
    "ID"
  ) ON DELETE CASCADE,
  CONSTRAINT "FK_ActivitySyncConnectionRuleSet_RuleSet" FOREIGN KEY ("ActivitySyncRuleSetID") REFERENCES "__mj_bizappscommon"."ActivitySyncRuleSet" (
    "ID"
  )
);

-- batch H4
CREATE TABLE "__mj_bizappscommon"."ActivitySyncExclusion" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "ActivitySyncRuleSetID" UUID NULL,
  "IdentityKind" VARCHAR(20) NOT NULL,
  "IdentityValue" VARCHAR(320) NOT NULL,
  "PersonID" UUID NULL,
  "Reason" TEXT NULL,
  "EffectiveFrom" TIMESTAMPTZ NULL,
  "EffectiveTo" TIMESTAMPTZ NULL,
  "IsEnabled" BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT "PK_ActivitySyncExclusion" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_ActivitySyncExclusion" UNIQUE (
    "ActivitySyncRuleSetID",
    "IdentityKind",
    "IdentityValue"
  ),
  CONSTRAINT "FK_ActivitySyncExclusion_RuleSet" FOREIGN KEY ("ActivitySyncRuleSetID") REFERENCES "__mj_bizappscommon"."ActivitySyncRuleSet" (
    "ID"
  ) ON DELETE CASCADE,
  CONSTRAINT "FK_ActivitySyncExclusion_Person" FOREIGN KEY ("PersonID") REFERENCES "__mj_bizappscommon"."Person" (
    "ID"
  ),
  CONSTRAINT "CK_ActivitySyncExclusion_IdentityKind" CHECK ("IdentityKind" IN ('Email', 'Phone', 'Handle', 'Domain')),
  CONSTRAINT "CK_ActivitySyncExclusion_Window" CHECK ("EffectiveFrom" IS NULL
  OR "EffectiveTo" IS NULL
  OR "EffectiveTo" >= "EffectiveFrom")
);

-- batch H5
CREATE TABLE "__mj_bizappscommon"."ActivitySyncRun" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "ActivitySyncConnectionID" UUID NOT NULL,
  "StartedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "EndedAt" TIMESTAMPTZ NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Running',
  "TriggerType" VARCHAR(20) NOT NULL DEFAULT 'Scheduled',
  "IsDryRun" BOOLEAN NOT NULL DEFAULT FALSE,
  "Fetched" INT NOT NULL DEFAULT 0,
  "Included" INT NOT NULL DEFAULT 0,
  "Excluded" INT NOT NULL DEFAULT 0,
  "Duplicates" INT NOT NULL DEFAULT 0,
  "Failed" INT NOT NULL DEFAULT 0,
  "ExtensionErrors" INT NOT NULL DEFAULT 0,
  "WatermarkBefore" TIMESTAMPTZ NULL,
  "WatermarkAfter" TIMESTAMPTZ NULL,
  "ErrorMessage" TEXT NULL,
  CONSTRAINT "PK_ActivitySyncRun" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_ActivitySyncRun_Connection" FOREIGN KEY ("ActivitySyncConnectionID") REFERENCES "__mj_bizappscommon"."ActivitySyncConnection" (
    "ID"
  ) ON DELETE CASCADE,
  CONSTRAINT "CK_ActivitySyncRun_Status" CHECK ("Status" IN ('Running', 'Completed', 'Failed', 'Cancelled')),
  CONSTRAINT "CK_ActivitySyncRun_TriggerType" CHECK ("TriggerType" IN ('Scheduled', 'Manual', 'Webhook', 'Backfill')),
  CONSTRAINT "CK_ActivitySyncRun_DryRunNoWatermark" CHECK ("IsDryRun" = FALSE OR "WatermarkAfter" IS NULL)
);

-- batch H6
CREATE TABLE "__mj_bizappscommon"."ActivitySyncRunDetail" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "ActivitySyncRunID" UUID NOT NULL,
  "ExternalID" VARCHAR(400) NOT NULL,
  "ExternalThreadID" VARCHAR(400) NULL,
  "OccurredAt" TIMESTAMPTZ NULL,
  "Decision" VARCHAR(20) NOT NULL,
  "DecidedByStage" VARCHAR(100) NULL,
  "ActivitySyncRuleID" UUID NULL,
  "ActivitySyncExclusionID" UUID NULL,
  "Reason" TEXT NULL,
  "Confidence" DECIMAL(5, 4) NULL,
  "AIPromptRunID" UUID NULL,
  "ActivityID" UUID NULL,
  "CapturedContent" TEXT NULL,
  "EncryptionKeyID" UUID NULL,
  CONSTRAINT "PK_ActivitySyncRunDetail" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_ActivitySyncRunDetail_Run" FOREIGN KEY ("ActivitySyncRunID") REFERENCES "__mj_bizappscommon"."ActivitySyncRun" (
    "ID"
  ) ON DELETE CASCADE,
  CONSTRAINT "FK_ActivitySyncRunDetail_Rule" FOREIGN KEY ("ActivitySyncRuleID") REFERENCES "__mj_bizappscommon"."ActivitySyncRule" (
    "ID"
  ),
  CONSTRAINT "FK_ActivitySyncRunDetail_Exclusion" FOREIGN KEY ("ActivitySyncExclusionID") REFERENCES "__mj_bizappscommon"."ActivitySyncExclusion" (
    "ID"
  ),
  CONSTRAINT "FK_ActivitySyncRunDetail_Activity" FOREIGN KEY ("ActivityID") REFERENCES "__mj_bizappscommon"."Activity" (
    "ID"
  ),
  CONSTRAINT "FK_ActivitySyncRunDetail_EncryptionKey" FOREIGN KEY ("EncryptionKeyID") REFERENCES "__mj"."EncryptionKey" (
    "ID"
  ),
  CONSTRAINT "CK_ActivitySyncRunDetail_Decision" CHECK ("Decision" IN ('Included', 'Excluded', 'Duplicate', 'Failed', 'WouldInclude', 'WouldExclude')),
  CONSTRAINT "CK_ActivitySyncRunDetail_Confidence" CHECK ("Confidence" IS NULL OR (
    "Confidence" >= 0 AND "Confidence" <= 1
  )),
  CONSTRAINT "CK_ActivitySyncRunDetail_ContentKey" CHECK ((
    "CapturedContent" IS NULL AND "EncryptionKeyID" IS NULL
  )
  OR (
    NOT "CapturedContent" IS NULL AND NOT "EncryptionKeyID" IS NULL
  )),
  CONSTRAINT "CK_ActivitySyncRunDetail_ActivityOnlyWhenIncluded" CHECK ("ActivityID" IS NULL OR "Decision" = 'Included')
);

-- batch H7
CREATE TABLE "__mj_bizappscommon"."ActivitySyncExtension" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Name" VARCHAR(200) NOT NULL,
  "Description" TEXT NULL,
  "DriverClass" VARCHAR(200) NOT NULL,
  "ActivitySyncConnectionID" UUID NULL,
  "ActivitySyncProviderTypeID" UUID NULL,
  "Sequence" INT NOT NULL DEFAULT 0,
  "FailurePolicy" VARCHAR(20) NOT NULL DEFAULT 'Skip',
  "TimeoutMS" INT NOT NULL DEFAULT 5000,
  "IsEnabled" BOOLEAN NOT NULL DEFAULT TRUE,
  "LastRunAt" TIMESTAMPTZ NULL,
  "LastError" TEXT NULL,
  CONSTRAINT "PK_ActivitySyncExtension" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_ActivitySyncExtension_Name" UNIQUE (
    "Name"
  ),
  CONSTRAINT "FK_ActivitySyncExtension_Connection" FOREIGN KEY ("ActivitySyncConnectionID") REFERENCES "__mj_bizappscommon"."ActivitySyncConnection" (
