  ) ON DELETE CASCADE,
  CONSTRAINT "FK_ActivitySyncExtension_ProviderType" FOREIGN KEY ("ActivitySyncProviderTypeID") REFERENCES "__mj_bizappscommon"."ActivitySyncProviderType" (
    "ID"
  ),
  CONSTRAINT "CK_ActivitySyncExtension_FailurePolicy" CHECK ("FailurePolicy" IN ('Skip', 'Abort')),
  CONSTRAINT "CK_ActivitySyncExtension_TimeoutMS" CHECK ("TimeoutMS" > 0 AND "TimeoutMS" <= 300000)
);

-- batch H8
ALTER TABLE "__mj_bizappscommon"."ActivitySyncConnection"
  ADD COLUMN "ActivitySyncProviderTypeID" UUID NULL,
  ADD COLUMN "StartAt" TIMESTAMPTZ NULL,
