  ADD COLUMN "EncryptionKeyID" UUID NULL,
  ADD COLUMN "StorageProviderID" UUID NULL,
  ADD COLUMN "MaxAttachmentBytes" BIGINT NULL;

-- batch H9
ALTER TABLE "__mj_bizappscommon"."ActivitySyncConnection"
  ADD CONSTRAINT "FK_ActivitySyncConnection_ProviderType" FOREIGN KEY ("ActivitySyncProviderTypeID") REFERENCES "__mj_bizappscommon"."ActivitySyncProviderType" (
    "ID"
  ),
