    "ID"
  ),
  ADD CONSTRAINT "CK_ActivitySyncConnection_ActivationWindow" CHECK ("StartAt" IS NULL OR "EndAt" IS NULL OR "EndAt" >= "StartAt"),
  ADD CONSTRAINT "CK_ActivitySyncConnection_SkippedPolicy" CHECK ("SkippedContentPolicy" IS NULL
  OR "SkippedContentPolicy" IN ('None', 'SubjectEncrypted', 'FullEncrypted')),
