SELECT * FROM __mj."spUpdateExistingEntitiesFromSchema"(p_excludedschemanames := (SELECT string_agg(DISTINCT "SchemaName", ',') FROM __mj."Entity" WHERE lower("SchemaName") <> lower('__mj_bizappscommon')));

ALTER TABLE "__mj_bizappscommon"."ActivitySyncConnectionRuleSet"
ADD COLUMN "__mj_CreatedAt" TIMESTAMPTZ NULL;

-- batch C2
UPDATE "__mj_bizappscommon"."ActivitySyncConnectionRuleSet" SET "__mj_CreatedAt" = NOW()
WHERE
  "__mj_CreatedAt" IS NULL;

-- batch C3
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT ns.nspname AS sch, dv.relname AS vw
    FROM pg_depend d
    JOIN pg_rewrite rw ON rw.oid = d.objid
    JOIN pg_class dv ON dv.oid = rw.ev_class AND dv.relkind = 'v'
    JOIN pg_namespace ns ON ns.oid = dv.relnamespace
    JOIN pg_class tc ON tc.oid = d.refobjid
    JOIN pg_attribute a ON a.attrelid = tc.oid AND a.attnum = d.refobjsubid
    WHERE tc.relname = 'ActivitySyncConnectionRuleSet' AND a.attname = '__mj_CreatedAt'
  LOOP
    EXECUTE format('DROP VIEW IF EXISTS %I.%I CASCADE', r.sch, r.vw);
  END LOOP;
END $$;
