-- batch H41
INSERT INTO __mj."ActionFilter" ("ID", "UserDescription", "UserComments", "Code", "CodeExplanation")
VALUES ('9270AA31-975F-49C3-A16C-82CD009FED16', 'Common: Status field changed in this save', 'Reusable transition detector for AfterUpdate bindings on any entity with a Status column (People, Organizations). MJ ships no seed ActionFilter rows (verified 2026-08-30) — the reusable piece upstream is the ActionFilterContext vocabulary this Code uses. Two behaviours to respect when attaching it: a CREATE reports no changes (DidFieldChange is false on insert), so never attach this to an AfterCreate-only binding; and filter evaluation is fail-closed — a prevented run still writes an ActionExecutionLog row.', 'return ActionFilterContext.DidFieldChange(''Status'');', 'True only when the Status field''s value actually differs across this save — the binding fires on the transition, not on every update.');

-- batch H42
INSERT INTO __mj."ActionFilter" ("ID", "UserDescription", "UserComments", "Code", "CodeExplanation")
VALUES ('EC35D675-FD23-4E99-81FF-87874BFE731C', 'Common: Status field changed to Ended in this save', 'The ''field changed TO value'' shape — written as a transition, never as ''status IS Ended'', which would re-fire on every later save of an ended record. Loose compare per the ActionFilterContext contract. Same caveats as the plain status-changed filter: false on create, fail-closed evaluation.', 'return ActionFilterContext.DidFieldChangeToValue(''Status'', ''Ended'');', 'True only on the save that moves Status to Ended, so a relationship''s end is logged exactly once per transition.');

-- batch H43
INSERT INTO __mj."AIAgent" ("ID", "Name", "Description", "LogoURL", "ParentID", "ExposeAsAction", "ExecutionOrder", "ExecutionMode", "EnableContextCompression", "ContextCompressionMessageThreshold", "ContextCompressionPromptID", "ContextCompressionMessageRetentionCount", "TypeID", "Status", "DriverClass", "IconClass", "ModelSelectionMode", "PayloadDownstreamPaths", "PayloadUpstreamPaths", "PayloadSelfReadPaths", "PayloadSelfWritePaths", "PayloadScope", "FinalPayloadValidation", "FinalPayloadValidationMode", "FinalPayloadValidationMaxRetries", "MaxCostPerRun", "MaxTokensPerRun", "MaxIterationsPerRun", "MaxTimePerRun", "MinExecutionsPerRun", "MaxExecutionsPerRun", "StartingPayloadValidation", "StartingPayloadValidationMode", "DefaultPromptEffortLevel", "ChatHandlingOption", "DefaultArtifactTypeID", "InvocationMode", "ArtifactCreationMode", "FunctionalRequirements", "TechnicalDesign", "InjectNotes", "MaxNotesToInject", "NoteInjectionStrategy", "InjectExamples", "MaxExamplesToInject", "ExampleInjectionStrategy", "IsRestricted", "MessageMode", "MaxMessages", "AttachmentStorageProviderID", "AttachmentRootPath", "InlineStorageThresholdBytes", "AgentTypePromptParams", "ScopeConfig", "NoteRetentionDays", "ExampleRetentionDays", "AutoArchiveEnabled", "RerankerConfiguration", "CategoryID", "AllowEphemeralClientTools", "DefaultStorageAccountID", "SearchScopeAccess", "AcceptUnregisteredFiles", "DefaultCoAgentID", "TypeConfiguration", "AllowMemoryWrite", "RecordingDefault", "RecordingStorageProviderID", "DefaultMediaCollectionID", "SupportsPlanMode", "AcceptsSkills", "SkillActivationMode", "RequirePlanMode", "ContextWindowMaxTokens", "CompactionTriggerPercent", "CompactionTargetPercent", "ConversationSummaryPromptID")
VALUES ('C30BAF99-D85D-4020-ADD3-8C97773AC749', 'Person Lifecycle Changed', 'The downstream reaction to a person''s lifecycle status changing (Active / Inactive / Deceased). Dispatched durably by the People·AfterUpdate Entity Action binding through Execute Agent, with the person''s data arriving as the Data payload (bound as ''Entity Object Data''). A deterministic Flow agent on purpose: it records the transition on the person''s timeline via Common.LogActivity and finishes — it creates work and completes, it never holds a run open waiting for anyone. Hosts extend the reaction by adding steps here (notify, enrich, hand off) instead of touching the binding.', NULL, NULL, TRUE, 0, 'Sequential', FALSE, NULL, NULL, NULL, '4F6A189B-C068-4736-9F23-3FF540B40FDD', 'Active', NULL, 'fa-solid fa-user-clock', 'Agent Type', '["*"]', '["*"]', NULL, NULL, NULL, NULL, 'Retry', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Fail', NULL, NULL, NULL, 'Any', 'Always', NULL, NULL, TRUE, 5, 'Relevant', FALSE, 3, 'Semantic', FALSE, 'None', NULL, NULL, NULL, NULL, NULL, NULL, 90, 180, TRUE, NULL, NULL, TRUE, NULL, 'None', FALSE, NULL, NULL, TRUE, NULL, NULL, NULL, TRUE, 'None', 'RequestedOnly', FALSE, NULL, NULL, NULL, NULL);

-- batch H44
INSERT INTO __mj."AIAgentStep" ("ID", "AgentID", "Name", "Description", "StepType", "StartingStep", "TimeoutSeconds", "RetryCount", "OnErrorBehavior", "ActionID", "SubAgentID", "PromptID", "ActionOutputMapping", "PositionX", "PositionY", "Width", "Height", "Status", "ActionInputMapping", "LoopBodyType", "Configuration")
VALUES ('65B3A8BD-585C-4712-BBD3-59751450A21F', 'C30BAF99-D85D-4020-ADD3-8C97773AC749', 'Log lifecycle change on the timeline', 'Records the status transition as a SystemEvent activity linked Regarding the person, through the one shared ActivityWriter. The Description carries the new status value; idempotency is deliberately NOT keyed (no EventKey) because a person can change status more than once and each transition belongs on the timeline.', 'Action', TRUE, 600, 0, 'fail', 'CD67D909-A87D-43E2-9F34-95E04A0DDE3C', NULL, NULL, '{
  "ActivityID": "loggedActivityID",
  "AlreadyPresent": "activityAlreadyPresent"
}', 80, 80, 220, 80, 'Active', '{
  "TypeCode": "static:SystemEvent",
  "Title": "static:Person lifecycle status changed",
  "Description": "data.Status",
  "EntityName": "static:MJ_BizApps_Common: People",
  "RecordID": "data.ID",
  "Source": "static:System"
}', NULL, NULL);

