CREATE OR REPLACE FUNCTION "__mj_bizappscommon"."spCreateRelationshipType"(
    p_id UUID DEFAULT NULL,
    p_name varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_category varchar(50) DEFAULT NULL,
    p_isdirectional BOOLEAN DEFAULT NULL,
    p_forwardlabel_clear boolean DEFAULT false,
    p_forwardlabel varchar(100) DEFAULT NULL,
    p_reverselabel_clear boolean DEFAULT false,
    p_reverselabel varchar(100) DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj_bizappscommon"."vwRelationshipTypes" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."RelationshipType"
        (
            "ID",
            "Name",
                "Description",
                "Category",
                "IsDirectional",
                "ForwardLabel",
                "ReverseLabel",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_category,
                COALESCE(p_isdirectional, TRUE),
                CASE WHEN p_forwardlabel_clear = true THEN NULL ELSE COALESCE(p_forwardlabel, NULL) END,
                CASE WHEN p_reverselabel_clear = true THEN NULL ELSE COALESCE(p_reverselabel, NULL) END,
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappscommon"."vwRelationshipTypes"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
