    "__mj_bizappscommon"."ActivitySyncRunDetail" AS a
LEFT OUTER JOIN
    "__mj_bizappscommon"."ActivitySyncRule" AS mjbizappscommonActivitySyncRule_ActivitySyncRuleID
  ON
    "a"."ActivitySyncRuleID" = mjbizappscommonActivitySyncRule_ActivitySyncRuleID."ID"
LEFT OUTER JOIN
    "__mj_bizappscommon"."ActivitySyncExclusion" AS mjbizappscommonActivitySyncExclusion_ActivitySyncExclusionID
  ON
    "a"."ActivitySyncExclusionID" = mjbizappscommonActivitySyncExclusion_ActivitySyncExclusionID."ID"
LEFT OUTER JOIN
