) RETURNS SETOF "__mj_bizappscommon"."vwActivitySyncProviderTypes" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."ActivitySyncProviderType"
        (
            "ID",
            "Code",
                "Name",
                "Description",
                "DriverClass",
                "IconClass",
                "SupportedKinds",
                "DefaultQualificationPolicy",
                "DefaultSkippedContentPolicy",
                "DefaultEncryptionKeyID",
                "DefaultStorageProviderID",
                "DefaultMaxAttachmentBytes",
                "Sequence",
                "IsSystem",
                "IsActive",
                "CalendarDriverClass"
        )
    VALUES
        (
            v_new_id,
            p_code,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_driverclass_clear = true THEN NULL ELSE COALESCE(p_driverclass, NULL) END,
                CASE WHEN p_iconclass_clear = true THEN NULL ELSE COALESCE(p_iconclass, NULL) END,
                CASE WHEN p_supportedkinds_clear = true THEN NULL ELSE COALESCE(p_supportedkinds, NULL) END,
