                CASE WHEN p_defaultstorageproviderid_clear = true THEN NULL ELSE COALESCE(p_defaultstorageproviderid, NULL) END,
                CASE WHEN p_defaultmaxattachmentbytes_clear = true THEN NULL ELSE COALESCE(p_defaultmaxattachmentbytes, NULL) END,
                COALESCE(p_sequence, 0),
                COALESCE(p_issystem, FALSE),
                COALESCE(p_isactive, TRUE),
                CASE WHEN p_calendardriverclass_clear = true THEN NULL ELSE COALESCE(p_calendardriverclass, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappscommon"."vwActivitySyncProviderTypes"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
