-- batch C8
-- Layered outer view vwPeople (hand-written over CodeGen's vwPeopleGenerated): adds the person's
-- primary job function (lowest-sequence PersonJobFunction). CASCADE also drops the People CRUD
-- functions typed on the view; the CodeGen section below recreates them and rebinds the view.
DROP VIEW IF EXISTS __mj_bizappscommon."vwPeople" CASCADE;
CREATE VIEW __mj_bizappscommon."vwPeople" AS
 SELECT g."ID",
    g."FirstName",
    g."LastName",
    g."MiddleName",
    g."Prefix",
    g."Suffix",
    g."PreferredName",
    g."Title",
    g."Email",
    g."Phone",
    g."DateOfBirth",
    g."Gender",
    g."PhotoURL",
    g."Bio",
    g."LinkedUserID",
    g."Status",
    g."__mj_CreatedAt",
    g."__mj_UpdatedAt",
    g."DisplayName",
    g."LinkedUser",
    addr."Line1" AS "PrimaryAddressLine1",
    addr."Line2" AS "PrimaryAddressLine2",
    addr."City" AS "PrimaryAddressCity",
    addr."StateProvince" AS "PrimaryAddressState",
    addr."PostalCode" AS "PrimaryAddressPostalCode",
    addr."Country" AS "PrimaryAddressCountry",
    addr."Latitude" AS "PrimaryAddressLatitude",
    addr."Longitude" AS "PrimaryAddressLongitude",
    "addrType"."Name" AS "PrimaryAddressType",
    COALESCE(cm_email."Value", g."Email") AS "PrimaryEmail",
    COALESCE(cm_phone."Value", g."Phone") AS "PrimaryPhone",
    emp_org."ID" AS "CurrentOrganizationID",
    emp_org."Name" AS "CurrentOrganizationName",
    emp_rel."Title" AS "CurrentJobTitle",
    primary_jf."JobFunctionID" AS "PrimaryJobFunctionID",
    primary_jf."JobFunctionName" AS "PrimaryJobFunction"
   FROM __mj_bizappscommon."vwPeopleGenerated" g
     LEFT JOIN __mj_bizappscommon."AddressLink" al ON al."RecordID"::text = g."ID"::text AND al."EntityID" = (( SELECT "Entity"."ID"
           FROM __mj."Entity"
          WHERE "Entity"."Name"::text = 'MJ_BizApps_Common: People'::text)) AND al."IsPrimary" = true
     LEFT JOIN __mj_bizappscommon."Address" addr ON addr."ID" = al."AddressID"
     LEFT JOIN __mj_bizappscommon."AddressType" "addrType" ON "addrType"."ID" = al."AddressTypeID"
     LEFT JOIN __mj_bizappscommon."ContactMethod" cm_email ON cm_email."PersonID" = g."ID" AND cm_email."IsPrimary" = true AND cm_email."ContactTypeID" = (( SELECT "ContactType"."ID"
           FROM __mj_bizappscommon."ContactType"
          WHERE "ContactType"."Name"::text = 'Email'::text))
     LEFT JOIN __mj_bizappscommon."ContactMethod" cm_phone ON cm_phone."PersonID" = g."ID" AND cm_phone."IsPrimary" = true AND cm_phone."ContactTypeID" = (( SELECT "ContactType"."ID"
           FROM __mj_bizappscommon."ContactType"
          WHERE "ContactType"."Name"::text = 'Mobile Phone'::text))
     LEFT JOIN LATERAL ( SELECT r."Title",
            r."ToOrganizationID"
           FROM __mj_bizappscommon."Relationship" r
             JOIN __mj_bizappscommon."RelationshipType" rt ON rt."ID" = r."RelationshipTypeID"
          WHERE rt."Name"::text = 'Employee'::text AND r."FromPersonID" = g."ID" AND r."Status"::text = 'Active'::text
          ORDER BY r."StartDate" DESC
         LIMIT 1) emp_rel ON true
     LEFT JOIN __mj_bizappscommon."Organization" emp_org ON emp_org."ID" = emp_rel."ToOrganizationID"
     LEFT JOIN LATERAL ( SELECT pjf."JobFunctionID",
            jf."Name" AS "JobFunctionName"
           FROM __mj_bizappscommon."PersonJobFunction" pjf
             JOIN __mj_bizappscommon."JobFunction" jf ON jf."ID" = pjf."JobFunctionID"
          WHERE pjf."PersonID" = g."ID"
          ORDER BY pjf."Sequence", jf."Name"
         LIMIT 1) primary_jf ON true;
GRANT SELECT ON __mj_bizappscommon."vwPeople" TO "cdp_UI", "cdp_Developer", "cdp_Integration";


