BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."JobFunction"
        (
            "ID",
            "Name",
                "Description",
                "Sequence",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                COALESCE(p_sequence, 0),
                COALESCE(p_status, 'Active')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappscommon"."vwJobFunctions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
