-- batch H9
-- Activity Sync Run Details permission lockdown for role DFAFCCEC-6A37-EF11-86D4-000D3A4E707E (exactly one existing row expected).
DO $perm$
BEGIN
  IF (SELECT count(*) FROM __mj."EntityPermission"
       WHERE "EntityID" = 'AC16B066-9460-44F5-B027-3FD397E61F34' AND "RoleID" = 'DFAFCCEC-6A37-EF11-86D4-000D3A4E707E') <> 1 THEN
    RAISE EXCEPTION 'Metadata_Sync v5.47.x: expected exactly one EntityPermission for Activity Sync Run Details and this role; cannot apply the permission lockdown.';
  END IF;
  UPDATE __mj."EntityPermission"
     SET "CanCreate" = TRUE, "CanRead" = FALSE, "CanUpdate" = FALSE, "CanDelete" = FALSE,
         "ReadRLSFilterID" = NULL, "CreateRLSFilterID" = NULL, "UpdateRLSFilterID" = NULL, "DeleteRLSFilterID" = NULL,
         "Type" = 'Allow'
   WHERE "EntityID" = 'AC16B066-9460-44F5-B027-3FD397E61F34' AND "RoleID" = 'DFAFCCEC-6A37-EF11-86D4-000D3A4E707E';
END
