  "EntityActionID" = 'C5AF459B-6757-4BC3-B890-B5CEBCD0E745',
  "ActionParamID" = 'F12EF739-720B-4FD4-8B9F-0656A756502E',
  "ValueType" = 'Script',
  "Value" = 'return { ID: EntityActionContext.entityObject.ID, Status: EntityActionContext.entityObject.Status };',
  "Comments" = 'Data — only the fields the Person Lifecycle Changed agent reads (data.ID, data.Status). A Script, not ''Entity Object Data'': this binding is Durable, and redaction always strips whole-record values from the task payload, so the agent would get no data (#197). LogValue true because MJ declares Execute Agent''s Data LogValue = false, which would strip it too; an id and a status are safe to persist. Add a field here only if it is equally safe to persist.',
  "LogValue" = TRUE
WHERE "ID" = 'D9FC0271-AA50-4B0C-A0D4-C29A0B4E1922';

-- batch H57
UPDATE __mj."EntityActionParam" SET
  "EntityActionID" = 'D7497F2F-DFC6-4B46-B3A5-D677A99A71DB',
  "ActionParamID" = '5A92E7F9-43F1-409E-93AB-B122C9A870D4',
  "ValueType" = 'Entity Field',
  "Value" = 'Status',
  "Comments" = 'Description ← the organization''s new Status value (Active / Inactive / Dissolved). LogValue true because this binding is Durable and Common.LogActivity declares Description LogValue = false (it can carry free text); redaction would otherwise strip it from the task payload and the activity would be written without its status. A status value is safe to persist.',
  "LogValue" = TRUE
WHERE "ID" = 'F4F23C56-C3E7-4244-BE84-26BED2006B71';

-- batch H58
INSERT INTO __mj."EntityActionParam" ("ID", "EntityActionID", "ActionParamID", "ValueType", "Value", "Comments", "LogValue")
VALUES ('F9DCDCCD-3ACD-4D05-971D-C9620ACA1725', 'D7497F2F-DFC6-4B46-B3A5-D677A99A71DB', '522170BB-9FA4-447D-9458-9C134B0985FA', 'Entity Field', 'ID', 'RecordID — a scalar, so it survives the redaction a durable binding''s params go through (whole-record ''Entity Object Data'' never does, #197). Feeds the Regarding link. No EventKey on purpose: a status can change repeatedly and every transition belongs on the timeline.', NULL);

