-- batch H65
INSERT INTO __mj."Query" ("ID", "Name", "CategoryID", "UserQuestion", "Description", "SQL", "TechnicalDescription", "OriginalSQL", "Feedback", "Status", "QualityRank", "ExecutionCostRank", "UsesTemplate", "AuditQueryRuns", "CacheEnabled", "CacheTTLMinutes", "CacheMaxSize", "EmbeddingVector", "EmbeddingModelID", "CacheValidationSQL", "Reusable", "ExternalDataSourceID", "IsMaterialized")
VALUES ('6C0A1000-0001-4000-A000-00000000000F', 'Common: Activity With Contact History', '6C0A1000-0000-4000-A000-000000000001', 'What is the context and prior activity history for a specific activity?', 'Retrieves the target activity and the linked contact''s prior activities for relative sentiment and tagging analysis.', '-- Context query for Activity Sentiment & Tagging feature pipeline.
-- Returns the target activity along with the linked contact''s prior activities for baseline comparison.
SELECT
    targetActivity.ID AS TargetActivityID,
    targetActivity.Title AS TargetTitle,
    targetActivity.Description AS TargetDescription,
    targetActivity.StartedAt AS TargetStartedAt,
    targetActivity.Direction AS TargetDirection,
    targetActivity.Status AS TargetStatus,
    targetActivity.Outcome AS TargetOutcome,
    targetActivity.Details AS TargetDetails,
    linkedPerson.ID AS LinkedPersonID,
    linkedPerson.DisplayName AS LinkedPersonName,
    priorActivities.ID AS PriorActivityID,
    priorActivities.Title AS PriorTitle,
    priorActivities.Description AS PriorDescription,
    priorActivities.StartedAt AS PriorStartedAt,
    priorActivities.Direction AS PriorDirection,
    priorActivities.Outcome AS PriorOutcome,
    priorActivities.SentimentScore AS PriorSentimentScore
FROM [__mj_BizAppsCommon].[vwActivities] AS targetActivity
OUTER APPLY (
    SELECT TOP 1
        al.RecordID AS PersonID
    FROM [__mj_BizAppsCommon].[vwActivityLinks] al
    WHERE al.ActivityID = targetActivity.ID
      AND al.Entity = ''MJ_BizApps_Common: People''
) AS targetPersonLink
LEFT JOIN [__mj_BizAppsCommon].[vwPeople] AS linkedPerson
    ON linkedPerson.ID = targetPersonLink.PersonID
OUTER APPLY (
    SELECT TOP 10
        a.ID,
        a.Title,
        a.Description,
        a.StartedAt,
        a.Direction,
        a.Outcome,
        a.SentimentScore
    FROM [__mj_BizAppsCommon].[vwActivities] a
    INNER JOIN [__mj_BizAppsCommon].[vwActivityLinks] al2
        ON al2.ActivityID = a.ID
       AND al2.Entity = ''MJ_BizApps_Common: People''
       AND al2.RecordID = targetPersonLink.PersonID
    WHERE a.ID <> targetActivity.ID
      AND a.StartedAt <= targetActivity.StartedAt
    ORDER BY a.StartedAt DESC
) AS priorActivities
WHERE targetActivity.ID = {{ ActivityID | sqlString }};
', 'Joins vwActivities to vwActivityLinks for linked People records, pulling the last 10 prior activities for baseline context. Parameters: ActivityID.', NULL, NULL, 'Approved', 9, 2, TRUE, FALSE, FALSE, NULL, NULL, '[0.0046330043114721775,-0.02773677371442318,-0.004453089088201523,-0.018819717690348625,-0.030256638303399086,-0.024424124509096146,0.004034058656543493,-0.01629779301583767,-0.02077728882431984,-0.0018599290633574128,-0.017678307369351387,-0.01789666898548603,-0.005104107782244682,0.020664166659116745,-0.001785511034540832,0.02545088715851307,-0.01555344182997942,0.0031827064231038094,0.031718719750642776,0.05128937587141991,0.017748331651091576,-0.011929996311664581,0.003006879473105073,0.007581827696412802,-0.03409946337342262,-0.012248106300830841,-0.027680659666657448,0.028195969760417938,0.07158753275871277,-0.09277085214853287,0.045736610889434814,0.014798274263739586,-0.010881548747420311,-0.024213818833231926,0.000002057988695014501,-0.009362474083900452,-0.023708917200565338,0.004511615261435509,0.021757574751973152,-0.01509308535605669,0.04427797719836235,0.0912434533238411,0.03129297122359276,0.0017710813554003835,-0.06370554119348526,0.02403063327074051,-0.03819704055786133,0.004477277863770723,-0.0032027061097323895,-0.004038070794194937,-0.008889183402061462,0.04868613928556442,-0.05181186646223068,-0.006769611965864897,0.08868207782506943,-0.017924001440405846,0.04905914142727852,0.046503953635692596,0.025338251143693924,-0.02349483221769333,0.049265503883361816,-0.05190013721585274,0.007591718807816505,-0.0034227112773805857,0.00430774362757802,0.012479727156460285,0.10632329434156418,0.026997366920113564,0.03732295334339142,-0.008851437829434872,0.09084554761648178,0.03873341903090477,0.0012856487883254886,-0.026104334741830826,-0.020949402824044228,-0.033481985330581665,-0.013318330980837345,-0.019550861790776253,-0.003387439763173461,-0.015921970829367638,0.009950287640094757,0.07274096459150314,0.018739188089966774,0.001320444513112