                CASE WHEN p_maxattachmentbytes_clear = true THEN NULL ELSE COALESCE(p_maxattachmentbytes, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappscommon"."vwActivitySyncConnections"
    WHERE "ID" = v_new_id;
END;
