    p_status varchar(50) DEFAULT NULL
) RETURNS SETOF "__mj_bizappscommon"."vwOrganizations" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappscommon"."Organization"
        (
