                CASE WHEN p_foundeddate_clear = true THEN NULL ELSE COALESCE(p_foundeddate, NULL) END,
                CASE WHEN p_taxid_clear = true THEN NULL ELSE COALESCE(p_taxid, NULL) END,
                COALESCE(p_status, 'Active')
